/* Greenpath Career OS · static, offline-capable data application (MIT license). */
(() => {
'use strict';
const D=window.APP_DATA;
if(!D){document.getElementById('app').textContent='Database tidak berhasil dimuat.';return;}
const STORAGE='greenpath-career-os:v1';
const TODAY=()=>new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Jakarta'});
const safe=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeURL=(v)=>/^https:\/\//i.test(String(v||''))?String(v):'';
const url=(v,text='Sumber ↗')=>safeURL(v)?`<a href="${safe(v)}" target="_blank" rel="noopener noreferrer" class="text-link">${safe(text)}</a>`:'<span class="small">Tautan belum tersedia</span>';
const DAY=86400000;
const dateFrom=(str)=>new Date((str||'1970-01-01')+'T00:00:00+07:00');
const pretty=(str)=>{if(!/^\d{4}-\d{2}-\d{2}$/.test(str||''))return 'Belum diumumkan';return dateFrom(str).toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Jakarta'})};
const dayDelta=(str)=>Math.ceil((dateFrom(str)-dateFrom(TODAY()))/DAY);
const pct=(v,max)=>max?Math.round(100*v/max):0;
const rupiah=(n)=>'Rp'+Math.round(n||0).toLocaleString('id-ID');
const def={statuses:{competitions:{},companies:{},scholarships:{},roadmap:{},skills:{},portfolios:{}},favorites:{},notes:{},applications:[],weekly:{},salary:{},customLinks:[],settings:{},createdAt:TODAY()};
let store;
try{store=Object.assign({},def,JSON.parse(localStorage.getItem(STORAGE)||'{}'));}catch(_){store=structuredClone(def)}
for(const k of ['statuses','favorites','notes','weekly','salary','settings'])if(!store[k]||typeof store[k]!=='object')store[k]={};
for(const k of Object.keys(def.statuses))if(!store.statuses[k]||typeof store.statuses[k]!=='object')store.statuses[k]={};
if(!Array.isArray(store.applications))store.applications=[];
const view={q:'',scope:'Semua',type:'Semua',verify:'Semua',sort:'score',favs:false,shown:20,month:'2026-11',resourceGroup:'Semua',trackerType:'Semua'};
const TITLES={dashboard:'Overview',roadmap:'Roadmap',competitions:'Bank Kompetisi',careers:'Green Jobs',scholarships:'S2 & Beasiswa',tracker:'Application Tracker',skills:'Skills & Portofolio',calendar:'Kalender',resources:'Curated Resources',finance:'Salary & Lifestyle'};
const icon={arrow:'↗',check:'✓',star:'★',calendar:'◷',dot:'•'};
const trackStages=['Ide','Disiapkan','Dikirim','Wawancara/Final','Selesai','Ditolak'];
const kindMap={competitions:D.competitions,companies:D.companies,scholarships:D.scholarships,portfolios:D.portfolios,roadmap:D.roadmap};
function get(kind,id){return (kindMap[kind]||[]).find(x=>x.id===id)}
function write(){try{localStorage.setItem(STORAGE,JSON.stringify(store));let e=document.getElementById('save-indicator');if(e)e.innerHTML='<span class="save-dot"></span> Tersimpan di perangkat ini';}catch(e){toast('Penyimpanan browser penuh atau diblokir. Ekspor backup JSON.')}}
function toast(msg){document.getElementById('toast-root').innerHTML=`<div class="toast">${safe(msg)}</div>`;clearTimeout(window._toaster);window._toaster=setTimeout(()=>document.getElementById('toast-root').innerHTML='',3200)}
function checked(kind,id){return store.statuses[kind]?.[id]===true}
function level(id){return Number(store.statuses.skills?.[id]||0)}
function status(kind,id){return store.statuses[kind]?.[id]||'Belum dipilih'}
function fav(kind,id){return !!store.favorites[kind+':'+id]}
function statusOptions(kind,id,values){return `<select class="control skill-control" data-change-status data-kind="${kind}" data-id="${safe(id)}" aria-label="Ubah status">${values.map(x=>`<option value="${safe(x)}" ${status(kind,id)===x?'selected':''}>${safe(x)}</option>`).join('')}</select>`}
function pHead(eyebrow,title,description,action=''){return `<div class="page-head"><div><div class="eyebrow">${safe(eyebrow)}</div><h1 class="heading">${safe(title)}</h1><p class="page-desc">${description}</p></div>${action}</div>`}
function buttonDetail(kind,id,label='Detail ↗'){return `<button class="button button-outline button-sm" data-detail="${kind}" data-id="${safe(id)}">${label}</button>`}
function buttonAdd(kind,id,label='+ Tracker'){return `<button class="button button-sm" data-add="${kind}" data-id="${safe(id)}">${safe(label)}</button>`}
function pill(text,tone='gray'){return `<span class="pill ${tone}">${safe(text)}</span>`}
function sourceFlag(v){return /resmi|official/i.test(v||'')?pill(v,'good'):/arsip/i.test(v||'')?pill(v,'gray'):pill(v||'Perlu cek','warn')}
function route(){let name=(location.hash||'#dashboard').slice(1).split('?')[0];return TITLES[name]?name:'dashboard'}
function go(dest){location.hash=dest;if(route()===dest){render();window.scrollTo(0,0)}}
function clearFilters(){Object.assign(view,{q:'',scope:'Semua',type:'Semua',verify:'Semua',sort:'score',favs:false,shown:20});}
function render(){
 let r=route();document.title=TITLES[r]+' · Greenpath';document.getElementById('current-section').textContent=TITLES[r];
 document.querySelectorAll('#nav-menu a').forEach(e=>e.classList.toggle('active',e.dataset.route===r));
 document.getElementById('nav-count-comps').textContent=D.competitions.length;
 document.getElementById('app').innerHTML=({dashboard:dashboard,roadmap:roadmap,competitions:competitions,careers:careers,scholarships:scholarships,tracker:tracker,skills:skills,calendar:calendar,resources:resources,finance:finance})[r]();
}
function availableComp(){return D.competitions.filter(x=>/resmi/i.test(x.verification)&&x.deadline&&dayDelta(x.deadline)>=0).sort((a,b)=>a.deadline.localeCompare(b.deadline))}
function countDone(){return Object.values(store.statuses.roadmap).filter(v=>v===true).length}
function dashboard(){
 const next=availableComp().slice(0,4);
 const primary=D.pathways.slice().sort((a,b)=>b.score-a.score).slice(0,3);
 const active=store.applications.filter(x=>!['Selesai','Ditolak'].includes(x.stage));
 const tasks=D.roadmap.filter(x=>!checked('roadmap',x.id)).slice(0,4);
 return `<section class="hero"><div class="hero-copy"><div class="eyebrow">2026 / 2032 · STRATEGIC CAREER PLAN</div><h1 class="display">Make your next move<br/>count<span style="color:#e4b38d">.</span></h1><p>Rute dari S1 Teknik Lingkungan menuju industri energi global, ESG consulting, financial independence, dan S2 Eropa — semuanya dalam satu ruang kerja.</p><span class="hero-badge">✳ Fokus niche: Industrial GHG · Methane · Climate Risk</span></div><div class="hero-decor" aria-hidden="true"><svg viewBox="0 0 180 180"><path d="M26 139c17-3 46-24 60-66 10-30 35-44 65-40-6 52-43 105-113 112M55 91c23 4 46 19 53 54"/><path d="M96 87l42-34M83 113l51-21" stroke-width="1.4"/></svg></div></section>
 <div class="kpi-grid"><div class="kpi-card"><div class="label">Kompetisi terkurasi</div><div class="value">${D.competitions.length}</div><div class="sub">Termasuk arsip & watchlist</div></div><div class="kpi-card"><div class="label">Perusahaan target</div><div class="value">${D.companies.length}</div><div class="sub">Big 4 · Energy · Global ESG</div></div><div class="kpi-card"><div class="label">Opsi S2 Eropa</div><div class="value">${D.scholarships.length}</div><div class="sub">Prioritas target 2029–2031</div></div><div class="kpi-card"><div class="label">Pipeline aktif</div><div class="value">${active.length}</div><div class="sub">Lamaran dan kompetisi berjalan</div></div></div>
 <div class="grid-two"><div class="card"><div class="card-head"><h2 class="card-title">Your 4-phase career map</h2><a href="#roadmap" class="inline-link">Roadmap lengkap ↗</a></div>${phasesMini()}</div><div class="card"><div class="card-head"><h2 class="card-title">Progress milestone</h2><span class="small">${countDone()} / ${D.roadmap.length}</span></div><div class="progress-track"><div class="progress-fill" style="width:${pct(countDone(),D.roadmap.length)}%"></div></div><div class="metric-line"><span class="small">Aktivitas menuju yudisium</span><strong>${pct(countDone(),D.roadmap.length)}%</strong></div><div class="highlight"><strong>North star 2027</strong><p class="small mb-0">Lulus S1 pada Agustus 2027, bangun portofolio GHG–methane dan water/climate risk, lalu masuk ESG/energy consulting atau graduate programme dengan kurva belajar tinggi.</p></div></div></div>
 <div class="grid-two" style="margin-top:19px"><div class="card"><div class="card-head"><h2 class="card-title">Deadline resmi mendatang</h2><a href="#calendar" class="inline-link">Buka kalender ↗</a></div><div class="feature-list">${next.length?next.map(x=>`<div class="feature-row"><span class="small-icon">◷</span><div><h4>${safe(x.name)}</h4><p>${pretty(x.deadline)} · ${safe(x.scope)} · ${safe(x.prize)}</p></div><div class="right-meta">${pill(dayDelta(x.deadline)+' hari','good')}<br/><button class="text-link" style="border:0;background:none;margin-top:8px" data-detail="competitions" data-id="${x.id}">Detail ↗</button></div></div>`).join(''):'<p class="small">Belum ada deadline resmi di masa depan. Periksa situs penyelenggara.</p>'}</div></div><div class="card"><div class="card-head"><h2 class="card-title">This week, do less but better</h2><span class="small">Prioritas skripsi tetap utama</span></div><div class="checkbox-list">${weeklyTodos()}</div><div class="highlight"><strong>Ritme yang disarankan</strong><p class="small mb-0">1 keluaran portofolio · 1 koneksi profesional · 1 aksi pasar per minggu. Maksimal 2 kompetisi aktif pada periode tugas akhir.</p></div></div></div>
 <div class="section-heading"><h2>Karier dengan momentum terbaik</h2><a href="#careers">Lihat 25 perusahaan ↗</a></div><div class="grid-three">${primary.map((x,i)=>`<div class="card"><div class="eyebrow">PATH 0${i+1}</div><h3 style="font-size:14px;line-height:1.5;margin:0 0 9px">${safe(x.name)}</h3><p class="small">${safe(x.entryRoles)}</p><div class="metric-line"><span class="small">Skor strategi</span><strong>${x.score}/5</strong></div><div class="progress-track"><div class="progress-fill" style="width:${x.score*20}%"></div></div></div>`).join('')}</div>
 <div class="section-heading"><h2>Backup & source transparency</h2></div><div class="card"><div class="grid-even"><div><h3 class="card-title">Semua progres tersimpan lokal</h3><p class="small">Simpan salinan JSON berkala. GitHub Pages tidak menyediakan database akun atau sinkronisasi lintas perangkat. Ekspor data sebelum membersihkan browser.</p><div class="row-actions"><button class="button button-sm" data-backup>↥ Ekspor backup JSON</button><button class="button button-outline button-sm" data-import-open>↧ Impor backup</button></div></div><div><h3 class="card-title">Akurasi informasi</h3><p class="small">Tanggal bersumber dari kombinasi edisi 2026, edisi 2027 resmi, dan proyeksi pengawasan. Hadiah bukan otomatis hadiah per peserta. Lowongan contoh bukan bukti vacancy tersedia pada 2027.</p><div class="row-actions"><button class="button button-outline button-sm" onclick="location.hash='resources'">Lihat sumber ↗</button></div></div></div></div>`;
}
function phasesMini(){return `<div class="feature-list">${[['2026–2027','Finish strong','Skripsi · 2 portofolio · kompetisi · internship'],['2027–2029','Market entry','Jakarta · ESG/energy analyst · consulting'],['2029–2031','Accelerate','GHG & methane niche · gaji · project ownership'],['2030–2032','International pivot','S2 Eropa · regional roles · climate strategy']].map((x,i)=>`<div class="feature-row"><span class="small-icon">${i+1}</span><div><h4>${x[0]} · ${x[1]}</h4><p>${x[2]}</p></div>${i===0?pill('Current','good'):''}</div>`).join('')}</div>`}
const defaultWeek=[['portfolio','Buat satu bukti progres portofolio methane/GHG'],['network','Hubungi satu profesional energy/ESG secara relevan'],['research','Tinjau 3 peluang kompetisi/kerja dan tandai syarat'],['degree','Pertahankan satu deliverable tugas akhir minggu ini']];
function weeklyTodos(){return defaultWeek.map(([id,x])=>`<label class="checkbox-line ${store.weekly[id]?'checked':''}"><input type="checkbox" data-weekly="${id}" ${store.weekly[id]?'checked':''}/>${safe(x)}</label>`).join('')}
function roadmap(){const now='2027-08-01';return pHead('THE LONG GAME','Roadmap 2026–2032','Rencana tahap demi tahap: kelulusan, masuk pasar kerja, spesialisasi industrial climate, akselerasi gaji, lalu S2 luar negeri.')+`<div class="roadmap-cards"><div class="phase-card current"><div class="phase-year">2026–27</div><h3>Build evidence</h3><p>Final-year S1, portofolio, kompetisi, internship, dan profil profesional.</p></div><div class="phase-card"><div class="phase-year">2027–29</div><h3>Enter the market</h3><p>Jakarta-first. Masuk consulting/energy dan kuasai pekerjaan yang bernilai bisnis.</p></div><div class="phase-card"><div class="phase-year">2029–31</div><h3>Specialize & earn</h3><p>Industrial GHG, methane MRV, climate risk, dan opsi pivot regional.</p></div><div class="phase-card"><div class="phase-year">2030–32</div><h3>Master's & mobility</h3><p>S2 Eropa atau global role, pilih berdasarkan ROI, pendanaan, dan visa kerja.</p></div></div><div class="section-heading"><h2>Milestone checklist</h2><span class="small">${countDone()}/${D.roadmap.length} selesai · checklist pribadi</span></div><div class="card"><div class="timeline">${D.roadmap.map(x=>`<div class="timeline-row"><div class="timeline-date">${pretty(x.date)}</div><div class="timeline-rail"><div class="timeline-node ${checked('roadmap',x.id)?'done':''}"></div></div><div class="timeline-content"><h4>${safe(x.stage)} — ${safe(x.objective)}</h4><p>${safe(x.deliverable)}${x.risk?' · '+safe(x.risk):''}</p><label class="mini-check"><input type="checkbox" data-roadmap="${x.id}" ${checked('roadmap',x.id)?'checked':''}/> ${checked('roadmap',x.id)?'Selesai':'Tandai selesai'}</label></div></div>`).join('')}</div></div><div class="section-heading"><h2>Pivot: teknik → bisnis → S2</h2></div><div class="grid-three"><div class="card"><div class="eyebrow">01</div><h3>Industry expertise</h3><p class="small">Metana, Scope 1–3, LDAR, risk assessment, inventaris emisi energi, serta ketidakpastian data.</p></div><div class="card"><div class="eyebrow">02</div><h3>Commercial fluency</h3><p class="small">NPV, MACC, CAPEX/OPEX, business case, sustainable finance, dan executive deck.</p></div><div class="card"><div class="eyebrow">03</div><h3>Global mobility</h3><p class="small">IELTS, pengalaman kerja terukur, rekomendasi profesional, beasiswa dan kebijakan visa pascastudi.</p></div></div>`}
function compList(){let list=D.competitions.filter(x=>{let q=view.q.toLowerCase();return (!q||(x.name+' '+x.category+' '+x.focus+' '+x.organizer+' '+x.prize).toLowerCase().includes(q))&&(view.scope==='Semua'||x.scope===view.scope)&&(view.type==='Semua'||x.category===view.type)&&(view.verify==='Semua'||(view.verify==='Resmi'?/resmi/i.test(x.verification):view.verify==='Pantau'?!/resmi/i.test(x.verification):/ya/i.test(x.eligibility)))&&(!view.favs||fav('competitions',x.id))});
 list.sort((a,b)=>view.sort==='score'?b.score-a.score:view.sort==='name'?a.name.localeCompare(b.name):view.sort==='deadline'?(a.deadline||'9999').localeCompare(b.deadline||'9999'):a.scope.localeCompare(b.scope));return list}
function compCard(x){return `<article class="list-card"><div class="list-card-top"><div class="badges">${pill(x.scope,x.scope==='Internasional'?'blue':'gray')}${sourceFlag(x.verification)}</div><button class="favorite ${fav('competitions',x.id)?'active':''}" title="Simpan favorit" aria-label="Favorit ${safe(x.name)}" data-fav="competitions" data-id="${x.id}">${fav('competitions',x.id)?'★':'☆'}</button></div><h3>${safe(x.name)}</h3><div class="small">${safe(x.organizer)} · ${safe(x.category)}</div><p>${safe(x.focus)}</p><div class="badges">${pill('Skor '+x.score+'/100','good')}${pill(x.prizeType)}${status('competitions',x.id)!=='Belum dipilih'?pill(status('competitions',x.id),'blue'):''}</div><div class="tagline ${/resmi/i.test(x.verification)?'mint':''}"><strong>Hadiah:</strong> ${safe(x.prize)}<br/><strong>Deadline sumber:</strong> ${x.deadline?pretty(x.deadline):safe(x.window)}${!/resmi/i.test(x.verification)?' · bukan deadline 2027 terkonfirmasi':''}</div><div class="list-card-footer"><span class="card-meta">${safe(x.id)} · ${safe(x.format)}</span><div class="row-actions">${buttonDetail('competitions',x.id)}${buttonAdd('competitions',x.id)}</div></div></article>`}
function compResults(){let a=compList();return `<div class="result-count" style="margin-bottom:12px">Menampilkan ${Math.min(a.length,view.shown)} dari ${a.length} hasil · ${D.competitions.length} total entri</div>${a.length?`<div class="item-grid">${a.slice(0,view.shown).map(compCard).join('')}</div>`:`<div class="empty"><div class="empty-icon">◇</div><h3>Tidak ditemukan</h3><p>Coba ubah filter atau hapus pencarian.</p></div>`}${a.length>view.shown?`<div style="text-align:center;margin-top:20px"><button class="button button-outline" data-more>Muat 20 hasil berikutnya</button></div>`:''}`}
function competitions(){let types=[...new Set(D.competitions.map(x=>x.category))].sort();return pHead('89 ENTRIES · NATIONAL + INTERNATIONAL','Competition intelligence','Bank kompetisi dari beberapa edisi, termasuk prize pool, persyaratan, rekam jejak, dan rekomendasi ide. Penyaring ini membantu memilih lomba yang paling worth it sebelum yudisium.',`<button class="button button-outline button-sm" data-export-comps>↓ Ekspor CSV</button>`)+`<div class="notice"><strong>Penting:</strong> “Resmi 2027” mengacu pada jadwal edisi terkait dalam workbook. Kategori lain mencakup arsip dan reminder berdasarkan tahun sebelumnya. Cek kelayakan semester serta tanggal final sebelum mendaftar.</div><div class="list-toolbar"><input class="control search-box" id="bank-search" placeholder="Cari nama lomba, penyelenggara, tema, atau hadiah..." value="${safe(view.q)}" data-filter="q"/><select class="control filter-select" data-filter="scope"><option>Semua</option><option ${view.scope==='Nasional'?'selected':''}>Nasional</option><option ${view.scope==='Internasional'?'selected':''}>Internasional</option></select><select class="control filter-select" data-filter="type"><option>Semua</option>${types.map(x=>`<option ${view.type===x?'selected':''}>${safe(x)}</option>`).join('')}</select><select class="control filter-select" data-filter="verify"><option>Semua</option><option value="Resmi" ${view.verify==='Resmi'?'selected':''}>Jadwal resmi</option><option value="Pantau" ${view.verify==='Pantau'?'selected':''}>Watchlist / Arsip</option><option value="Ya" ${view.verify==='Ya'?'selected':''}>Kelayakan potensial</option></select><select class="control filter-select" data-filter="sort"><option value="score" ${view.sort==='score'?'selected':''}>Skor tertinggi</option><option value="deadline" ${view.sort==='deadline'?'selected':''}>Deadline paling dekat</option><option value="name" ${view.sort==='name'?'selected':''}>Nama A–Z</option></select><label class="checkbox-line"><input type="checkbox" data-favs ${view.favs?'checked':''}/> Favorit saja</label></div><div id="comp-results">${compResults()}</div>`}
function jobCard(x){return `<article class="list-card"><div class="list-card-top"><div class="badges">${pill('Tier '+x.tier,x.tier==='A'?'good':'gray')}${pill(x.stage,'blue')}</div><button class="favorite ${fav('companies',x.id)?'active':''}" data-fav="companies" data-id="${x.id}">${fav('companies',x.id)?'★':'☆'}</button></div><h3>${safe(x.name)}</h3><div class="small">${safe(x.track)}</div><p><strong>Target role:</strong> ${safe(x.roles)}</p><p>${safe(x.reason)}</p><div class="tagline mint">Work style hypothesis: ${safe(x.workstyle)}. Bukan jaminan remote maupun vacancy aktif.</div><div class="list-card-footer"><span class="card-meta">${safe(x.stage)} · ${safe(x.entry)}</span><div class="row-actions">${buttonDetail('companies',x.id)}${buttonAdd('companies',x.id)}</div></div></article>`}
function careers(){let q=view.q.toLowerCase();let list=D.companies.filter(x=>(x.name+' '+x.track+' '+x.roles).toLowerCase().includes(q)&&(view.type==='Semua'||x.tier===view.type)&&(!view.favs||fav('companies',x.id)));return pHead('CAREER TARGETS','Energy, ESG & Green Jobs','Masuk pasar melalui ESG/Climate Assurance atau E&S Consulting, lalu spesialisasi industrial GHG, methane MRV, dan climate risk. Semua entri adalah target perusahaan, bukan lowongan aktif.')+`<div class="grid-three" style="margin-bottom:20px"><div class="card"><div class="eyebrow">ENTRY · 2027</div><h3>Big 4 & E&S Consulting</h3><p class="small">EY, PwC, ERM, sustainability assurance, environmental consulting dan industrial assessment.</p></div><div class="card"><div class="eyebrow">NICHE · 2028+</div><h3>GHG & Methane</h3><p class="small">Carbon inventory, methane measurement, industrial decarbonization, cost abatement.</p></div><div class="card"><div class="eyebrow">EXIT · 2030+</div><h3>Strategy & international</h3><p class="small">Energy transition, climate finance, multinational corporate ESG, regional roles.</p></div></div><div class="list-toolbar"><input class="control search-box" data-filter="q" placeholder="Cari perusahaan atau posisi..." value="${safe(view.q)}"/><select class="control" data-filter="type"><option>Semua</option><option ${view.type==='A'?'selected':''}>A</option><option ${view.type==='B'?'selected':''}>B</option><option ${view.type==='C'?'selected':''}>C</option></select><label class="checkbox-line"><input type="checkbox" data-favs ${view.favs?'checked':''}/> Favorit saja</label><span class="result-count">${list.length} perusahaan</span></div><div class="item-grid">${list.map(jobCard).join('')}</div><div class="section-heading"><h2>Career pathway scoring</h2><span class="small">Skor strategi subjektif, bukan probabilitas diterima</span></div><div class="card table-wrap"><table class="simple-table"><thead><tr><th>Pathway</th><th>Entry</th><th>Growth</th><th>Lifestyle</th><th>Global</th><th>Score / 5</th></tr></thead><tbody>${D.pathways.map(x=>`<tr><td>${safe(x.name)}</td><td>${x.entry}/5</td><td>${x.growth}/5</td><td>${x.lifestyle}/5</td><td>${x.international}/5</td><td>${x.score}</td></tr>`).join('')}</tbody></table></div>`}
function scholarshipCard(x){return `<article class="list-card"><div class="list-card-top"><div class="badges">${pill(x.country,'blue')}${pill(x.intake,'good')}</div><button class="favorite ${fav('scholarships',x.id)?'active':''}" data-fav="scholarships" data-id="${x.id}">${fav('scholarships',x.id)?'★':'☆'}</button></div><h3>${safe(x.programme)}</h3><div class="small">${safe(x.name)} · ${safe(x.bridge)}</div><p>${safe(x.why)}</p><div class="tagline"><strong>Pendanaan:</strong> ${safe(x.funding)}<br/><strong>Syarat penting:</strong> ${safe(x.experience)}</div><div class="list-card-footer"><span class="card-meta">Recheck: ${pretty(x.recheck)}</span><div class="row-actions">${buttonDetail('scholarships',x.id)}${buttonAdd('scholarships',x.id)}</div></div></article>`}
function scholarships(){const list=D.scholarships.filter(x=>(x.name+' '+x.programme+' '+x.country+' '+x.bridge).toLowerCase().includes(view.q.toLowerCase())&&(!view.favs||fav('scholarships',x.id)));return pHead('STUDY ABROAD · 2029–2032','Master’s in Europe','Environmental Engineering / Water Resources, Sustainability & Economics, serta Education / Public Policy. Pilih S2 berdasarkan ROI karier, funding, persyaratan pengalaman, dan rencana pascastudi.')+`<div class="notice green"><strong>Waktu masuk yang disarankan:</strong> yudisium Agustus 2027 → pengalaman kerja 2027–2029 → pantau intake 2030. DAAD EPOS dan Chevening mensyaratkan pengalaman kerja pasca-S1 pada jalur tertentu; Chevening juga mewajibkan kembali ke negara asal selama dua tahun.</div><div class="grid-three" style="margin-bottom:19px"><div class="card"><div class="eyebrow">TRACK A</div><h3>Environment & Water</h3><p class="small">Hydrology, geo-information, flooding, engineering, resilience.</p></div><div class="card"><div class="eyebrow">TRACK B</div><h3>Business & Economics</h3><p class="small">Energy economics, climate finance, sustainable investment, policy.</p></div><div class="card"><div class="eyebrow">TRACK C</div><h3>Education & Policy</h3><p class="small">Environmental governance, global development, capacity building.</p></div></div><div class="list-toolbar"><input class="control search-box" data-filter="q" placeholder="Cari program, negara, beasiswa..." value="${safe(view.q)}"/><label class="checkbox-line"><input type="checkbox" data-favs ${view.favs?'checked':''}/> Favorit saja</label><span class="result-count">${list.length} opsi</span></div><div class="item-grid">${list.map(scholarshipCard).join('')}</div>`}
function tracker(){let apps=store.applications.filter(x=>view.trackerType==='Semua'||x.type===view.trackerType);let count=(stage)=>apps.filter(x=>x.stage===stage).length;return pHead('EXECUTION BOARD','Application tracker','Gunakan satu pipeline untuk kompetisi, lamaran kerja, dan aplikasi beasiswa. Pindahkan kartu antar kolom atau edit detailnya kapan saja.',`<button class="button" data-new-app>+ Tambah aplikasi</button>`)+`<div class="notice green">Semua perubahan disimpan otomatis di browser ini. Klik “Backup data” untuk memindahkan progres ke perangkat lain. Kamu bisa drag & drop kartu pada desktop.</div><div class="list-toolbar"><select class="control" data-tracker-type><option>Semua</option><option value="competitions" ${view.trackerType==='competitions'?'selected':''}>Kompetisi</option><option value="companies" ${view.trackerType==='companies'?'selected':''}>Pekerjaan</option><option value="scholarships" ${view.trackerType==='scholarships'?'selected':''}>Beasiswa</option><option value="custom" ${view.trackerType==='custom'?'selected':''}>Lainnya</option></select><span class="result-count">${apps.length} aplikasi tercatat</span></div><div class="kanban">${trackStages.map(stage=>`<div class="lane" data-lane="${safe(stage)}"><h3>${safe(stage)} <span>${count(stage)}</span></h3>${apps.filter(x=>x.stage===stage).map(x=>`<div class="kanban-card" draggable="true" data-card-id="${safe(x.id)}"><div class="badges">${pill(x.type==='companies'?'Pekerjaan':x.type==='competitions'?'Lomba':x.type==='scholarships'?'S2':'Lainnya','gray')}</div><strong style="margin-top:8px">${safe(x.title)}</strong><p>${x.deadline?'Deadline '+pretty(x.deadline):'Belum ada deadline'} · ${safe(x.next||'Belum ada next action')}</p><div class="row-actions"><button class="button button-outline button-sm" data-edit-app="${safe(x.id)}">Edit ↗</button></div></div>`).join('')}</div>`).join('')}</div>${apps.length===0?`<div class="empty"><div class="empty-icon">▤</div><h3>Pipeline masih kosong</h3><p>Tambahkan dari Bank Kompetisi, Green Jobs, atau S2 Eropa agar mulai terisi.</p><button class="button" onclick="location.hash='competitions'">Cari peluang</button></div>`:''}`}
function skills(){const names=['Belum mulai','Dasar','Dipraktikkan','Bukti portofolio'];let practiced=D.skills.filter((x,i)=>level('sk'+i)>=2).length;return pHead('EXECUTION · PROOF OF WORK','Skills & portofolio','Berhenti mengumpulkan kursus tanpa hasil. Setiap skill harus berujung pada output yang bisa dinilai recruiter, mentor, atau reviewer beasiswa.')+`<div class="grid-even"><div class="card"><div class="card-head"><h2 class="card-title">Skills maturity</h2><span class="small">${practiced} / ${D.skills.length} sudah dipraktikkan</span></div><div class="progress-track"><div class="progress-fill" style="width:${pct(practiced,D.skills.length)}%"></div></div><p class="small">Ubah level per skill. Level “Bukti portofolio” berarti ada file/metode yang dapat ditunjukkan.</p><div class="feature-list">${D.skills.map((x,i)=>`<div class="skill-row"><div class="skill-info"><h3>${safe(x[0])}</h3><p>${safe(x[1])} · Prioritas ${safe(x[2])} · ${url(x[7],'Referensi ↗')}</p></div><div class="skill-bar" aria-hidden="true">${[1,2,3].map(j=>`<div class="skill-segment ${level('sk'+i)>=j?'active':''}"></div>`).join('')}</div><select class="control skill-control" data-skill="sk${i}">${names.map((name,j)=>`<option value="${j}" ${level('sk'+i)===j?'selected':''}>${name}</option>`).join('')}</select></div>`).join('')}</div></div><div class="card"><div class="card-head"><h2 class="card-title">Portfolio principles</h2></div><p class="quote">Show the method. Show the data. Show the decision. Explain uncertainty.</p><div class="feature-list"><div class="feature-row"><span class="small-icon">1</span><div><h4>Engineering credibility</h4><p>Audit trail, data quality, unit checking, engineering assumptions.</p></div></div><div class="feature-row"><span class="small-icon">2</span><div><h4>Business decisions</h4><p>Scenarios, costs, NPV, abatement options, feasibility and risks.</p></div></div><div class="feature-row"><span class="small-icon">3</span><div><h4>International communication</h4><p>Executive presentation in English and transparent methodology notes.</p></div></div></div><div class="highlight"><strong>Primary niche</strong><p class="small mb-0">Industrial Greenhouse Gas Accounting → Methane Management → Climate Risk & Strategy. Environmental and education interests remain as adjacent options.</p></div></div></div><div class="section-heading"><h2>8 reusable portfolio concepts</h2><span class="small">Satu proyek → beberapa kompetisi & interview</span></div><div class="item-grid">${D.portfolios.map(x=>`<article class="list-card"><div class="list-card-top"><div class="badges">${pill(x.sector,'good')}</div></div><h3>${safe(x.name)}</h3><p><strong>Data:</strong> ${safe(x.data)}</p><p><strong>Deliverable:</strong> ${safe(x.deliverable)}</p><p><strong>Reuse:</strong> ${safe(x.uses)}</p><div class="list-card-footer">${statusOptions('portfolios',x.id,['Belum dipilih','Riset','Dikerjakan','Selesai'])}<button class="button button-outline button-sm" data-detail="portfolios" data-id="${x.id}">Catatan ↗</button></div></article>`).join('')}</div>`}
function calendarEvents(){const a=[];for(const x of D.competitions){if(x.deadline && /resmi/i.test(x.verification))a.push({date:x.deadline,type:'Lomba',name:x.name,id:x.id})}for(const x of D.roadmap){if(x.date)a.push({date:x.date,type:'Milestone',name:x.objective,id:x.id})}for(const x of store.applications){if(x.deadline)a.push({date:x.deadline,type:'Tracker',name:x.title,id:x.id})}return a}
function calendar(){const [y,m]=view.month.split('-').map(Number),first=new Date(y,m-1,1),days=new Date(y,m,0).getDate(),offset=(first.getDay()+6)%7;const events=calendarEvents();let cells=[];for(let i=0;i<Math.ceil((days+offset)/7)*7;i++){let day=i-offset+1,isValid=day>0&&day<=days,ds=isValid?`${y}-${String(m).padStart(2,'0')}-${String(day).padStart(2,'0')}`:'',e=events.filter(z=>z.date===ds);cells.push(`<div class="day ${!isValid?'other':''} ${ds===TODAY()?'today':''}">${isValid?`<strong>${day}</strong>${e.length?`<div class="day-events">${e.slice(0,2).map(z=>`<div><span class="day-dot"></span> ${safe(z.name).slice(0,23)}</div>`).join('')}${e.length>2?'+'+(e.length-2)+' lainnya':''}</div>`:''}`:''}</div>`)}const monthName=first.toLocaleDateString('id-ID',{month:'long',year:'numeric'});const monthEvents=events.filter(e=>e.date.startsWith(view.month)).sort((a,b)=>a.date.localeCompare(b.date));return pHead('TIME MANAGEMENT','Kalender & deadline','Tanggal dari bank hanya muncul sebagai deadline jika ditandai resmi untuk siklus terkait. Milestone roadmap dan deadline custom juga tampil di sini.')+`<div class="grid-two"><div class="card"><div class="calendar-head"><button class="button button-outline button-sm" data-month="prev">←</button><h3>${safe(monthName)}</h3><button class="button button-outline button-sm" data-month="next">→</button></div><div class="calendar-grid">${['Sen','Sel','Rab','Kam','Jum','Sab','Min'].map(d=>`<div class="weekday">${d}</div>`).join('')}${cells.join('')}</div><p class="small" style="margin-top:18px">Titik hijau: kompetisi terjadwal, target pribadi, atau deadline pipeline. Tanggal sumber lama tidak otomatis digeser ke 2027.</p></div><div class="card"><div class="card-head"><h2 class="card-title">Agenda ${safe(monthName)}</h2><span class="small">${monthEvents.length} peristiwa</span></div><div class="feature-list">${monthEvents.length?monthEvents.map(x=>`<div class="feature-row"><span class="small-icon">${x.type==='Lomba'?'♜':x.type==='Tracker'?'▣':'✓'}</span><div><h4>${safe(x.name)}</h4><p>${pretty(x.date)} · ${safe(x.type)}</p></div></div>`).join(''):'<div class="empty"><h3>Tidak ada tanggal tercatat</h3><p>Gunakan bulan lain atau tambahkan deadline di tracker.</p></div>'}</div></div></div>`}
function resources(){const filtered=D.resources.filter(x=>(view.resourceGroup==='Semua'||x.group===view.resourceGroup)&&(x.name+' '+x.description).toLowerCase().includes(view.q.toLowerCase()));const people=D.people.filter(x=>(x.name+' '+x.topic).toLowerCase().includes(view.q.toLowerCase()));return pHead('SIGNAL OVER NOISE','Curated resources & people','Kurasi sumber peluang ESG, climate jobs, S2 Eropa, riset industri, dan kreator Indonesia. Tautan kreator berupa pencarian bila profil resminya belum dapat diverifikasi.')+`<div class="notice green">Sumber resmi diprioritaskan untuk deadline, beasiswa, dan syarat pelamar. Kreator/komunitas berguna sebagai radar; setiap informasi perlu diperiksa kembali ke penyelenggara.</div><div class="list-toolbar"><input class="control search-box" data-filter="q" placeholder="Cari portal, orang, atau topik..." value="${safe(view.q)}"/><select class="control" data-resource-group><option>Semua</option>${[...new Set(D.resources.map(x=>x.group))].map(g=>`<option ${g===view.resourceGroup?'selected':''}>${safe(g)}</option>`).join('')}</select></div><div class="section-heading"><h2>Portal & database</h2><span class="small">${filtered.length} sumber</span></div><div class="resource-grid">${filtered.map(x=>`<article class="resource-card"><div class="badges">${pill(x.group,'good')}${pill(x.type)}</div><h3>${safe(x.name)}</h3><p>${safe(x.description)}</p><div class="list-card-footer">${url(x.url,'Kunjungi ↗')}<span class="small">${safe(x.confidence)}</span></div></article>`).join('')}</div><div class="section-heading"><h2>Kreator & praktisi Indonesia</h2><span class="small">${people.length} kontak referensi</span></div><div class="resource-grid">${people.map(x=>`<article class="resource-card"><div class="badges">${pill(x.type,'blue')}</div><h3>${safe(x.name)}</h3><div class="small">${safe(x.handle)}</div><p>${safe(x.topic)}</p><div class="list-card-footer">${url(x.url,'Cari profil ↗')}<span class="small">Profil perlu diverifikasi</span></div></article>`).join('')}</div><div class="section-heading"><h2>Spreadsheet arsip</h2></div><div class="card"><div class="row-actions"><a class="button button-outline button-sm" href="downloads/COMPETITION_MEGA_BANK_2026_2027.xlsx" download>↓ 89 Kompetisi (.xlsx)</a><a class="button button-outline button-sm" href="downloads/energy_climate_career_compass_2027_2032.xlsx" download>↓ Career Compass (.xlsx)</a></div><p class="small" style="margin-bottom:0">Arsip sumber awal website. Perubahan status di web tidak otomatis menulis ulang file Excel.</p></div><div class="section-heading"><h2>Notes & reading inbox</h2></div><div class="card"><p class="small">Gunakan ruang ini untuk mencatat newsletter, komunitas, akun yang berguna, atau insight dari diskusi dengan alumni.</p><textarea class="control note-input" id="reading-notes" placeholder="Contoh: newsletter yang worth it, link live session, alumni yang bisa dihubungi...">${safe(store.notes.resources||'')}</textarea><div style="text-align:right;margin-top:9px"><button class="button button-sm" data-save-reading>Simpan catatan</button></div></div>`}
function computeOffer(key){let x=store.salary[key]||{},net=Number(x.net)||0,housing=Number(x.housing)||0,living=Number(x.living)||0,bonus=Number(x.bonus)||0,hours=Number(x.hours)||40,monthly=net-housing-living,annual=12*monthly+bonus,eff=(net*12+bonus)/(Math.max(hours,1)*52);return {monthly,annual,eff}}
function offerForm(key,title){const x=store.salary[key]||{};const r=computeOffer(key);return `<div class="card"><div class="card-head"><h2 class="card-title">${title}</h2>${pill(key==='a'?'Jakarta / company A':'Remote / company B','blue')}</div><div class="form-field"><label>Nama perusahaan / opsi</label><input class="control" data-salary="${key}" data-field="company" value="${safe(x.company||'')}" placeholder="Mis. Big 4 / multinational"/></div><div class="form-grid"><div class="form-field"><label>Take-home pay bulanan (Rp)</label><input class="control" type="number" min="0" data-salary="${key}" data-field="net" value="${safe(x.net||'')}" placeholder="9000000"/></div><div class="form-field"><label>Bonus bersih / tahun (Rp)</label><input class="control" type="number" min="0" data-salary="${key}" data-field="bonus" value="${safe(x.bonus||'')}" placeholder="0"/></div><div class="form-field"><label>Sewa / housing bulanan (Rp)</label><input class="control" type="number" min="0" data-salary="${key}" data-field="housing" value="${safe(x.housing||'')}" placeholder="2500000"/></div><div class="form-field"><label>Makan, transport, lainnya (Rp)</label><input class="control" type="number" min="0" data-salary="${key}" data-field="living" value="${safe(x.living||'')}" placeholder="3000000"/></div><div class="form-field"><label>Jam kerja per minggu</label><input class="control" type="number" min="1" max="100" data-salary="${key}" data-field="hours" value="${safe(x.hours||40)}"/></div><div class="form-field"><label>Perjalanan dinas malam/bulan</label><input class="control" type="number" min="0" data-salary="${key}" data-field="travel" value="${safe(x.travel||0)}"/></div></div><div class="finance-result" id="offer-result-${key}"><div class="small">Estimasi tabungan tahunan</div><strong>${rupiah(r.annual)}</strong><p class="small">Tabungan per bulan tanpa bonus: ${rupiah(r.monthly)} · Pendapatan net/jam: ${rupiah(r.eff)}</p></div></div>`}
function finance(){return pHead('FINANCIAL FREEDOM · QUALITY OF LIFE','Salary & lifestyle lab','Bandingkan dua tawaran berdasarkan pendapatan bersih, biaya hidup, tabungan tahunan, dan pendapatan efektif per jam — tidak hanya angka gaji nominal.')+`<div class="notice"><strong>Input harus berupa take-home pay (net), bukan gaji gross.</strong> Kalkulasi ini belum memasukkan inflasi, biaya pindah, pajak tambahan, biaya kesehatan, kurs, atau penyesuaian biaya hidup yang lebih kompleks.</div><div class="grid-even">${offerForm('a','Offer A')}${offerForm('b','Offer B')}</div><div class="section-heading"><h2>Career decision principles</h2></div><div class="grid-three"><div class="card"><div class="eyebrow">01 · GROWTH</div><h3>Skill & role ownership</h3><p class="small">Prioritaskan tanggung jawab analitis, portofolio proyek, dan peningkatan kemampuan yang langka di industri.</p></div><div class="card"><div class="eyebrow">02 · COMFORT</div><h3>Effective hourly rate</h3><p class="small">Gaji nominal tinggi belum tentu menghasilkan kualitas hidup lebih baik bila lembur dan travel ekstrem.</p></div><div class="card"><div class="eyebrow">03 · OPTIONALITY</div><h3>Mobility & study ROI</h3><p class="small">Pertimbangkan benefit reputasi global, pengalaman yang diterima beasiswa, dan akses ke jalur internasional.</p></div></div><div class="highlight"><strong>Target perencanaan (bukan data gaji terjamin)</strong><p class="small mb-0">Entry 2027: Rp8–12 juta gross/bulan (aspiratif); 2029–30: Rp15–25 juta; 2031+: Rp25–40 juta+. Angka hanya sasaran untuk evaluasi personal. Gunakan data job offer yang nyata untuk pengambilan keputusan.</p></div>`}
function detailData(kind,x){if(kind==='competitions')return [['Penyelenggara',x.organizer],['Cakupan',x.scope],['Fokus',x.focus],['Kategori',x.category],['Hadiah',x.prize],['Jenis hadiah',x.prizeType],['Deadline sumber',x.deadline?pretty(x.deadline):x.window],['Siklus sumber',x.cycle],['Status verifikasi',x.verification],['Kelayakan',x.eligibility],['Format',x.format],['Catatan kritis',x.warning],['Skor prioritas',x.score+'/100']];if(kind==='companies')return [['Kategori',x.track],['Prioritas','Tier '+x.tier],['Role keywords',x.roles],['Alasan',x.reason],['Dugaan gaya kerja',x.workstyle],['Career stage',x.stage],['Langkah berikut',x.next]];if(kind==='scholarships')return [['Beasiswa',x.name],['Negara',x.country],['Jembatan bidang',x.bridge],['Pendanaan',x.funding],['Pengalaman',x.experience],['Target intake',x.intake],['Waktu cek ulang',pretty(x.recheck)],['Alasan',x.why]];if(kind==='portfolios')return [['Sektor',x.sector],['Bisa dipakai untuk',x.uses],['Data / model',x.data],['Output',x.deliverable],['Benefit karier',x.benefit]];return []}
function showModal(markup){document.getElementById('modal-root').innerHTML=`<div class="modal-overlay" id="overlay"><div class="modal" role="dialog" aria-modal="true" aria-label="Detail"><div class="modal-head"><div class="eyebrow">GREENPATH · PERSONAL WORKSPACE</div><button class="icon-button" data-close aria-label="Tutup dialog">×</button></div>${markup}</div></div>`;document.querySelector('[data-close]')?.focus()}
function closeModal(){document.getElementById('modal-root').innerHTML=''}
function detail(kind,id){const x=get(kind,id);if(!x)return;const title=x.name||x.programme||x.objective;const fields=detailData(kind,x);const link=x.url||x.source||'';showModal(`<h2 style="font:800 22px/1.35 Manrope,sans-serif;margin:0 0 13px">${safe(title)}</h2><div class="badges" style="margin-bottom:14px">${pill(kind==='competitions'?'Kompetisi':kind==='companies'?'Perusahaan':kind==='scholarships'?'S2 & Beasiswa':'Portofolio','good')}${kind==='competitions'?sourceFlag(x.verification):''}</div>${fields.map(([l,v])=>`<div class="meta-pair"><span>${safe(l)}</span><span>${safe(v)}</span></div>`).join('')}<div class="form-field" style="margin-top:17px"><label>Catatan pribadimu</label><textarea class="control" id="item-note" placeholder="Eligibility, ide, follow-up, hal yang perlu ditanyakan...">${safe(store.notes[kind+':'+id]||'')}</textarea></div><div class="modal-actions">${link?url(link,'Buka sumber resmi / referensi ↗'):''}<button class="button button-outline" data-save-item-note="${kind}" data-id="${id}">Simpan catatan</button>${kind==='portfolios'?'':buttonAdd(kind,id)}</div>`)}
function addApp(kind,id){const x=get(kind,id);if(!x)return;let existing=store.applications.find(a=>a.ref===id&&a.type===kind);if(existing){toast('Sudah ada di tracker');go('tracker');return}let title=x.name||x.programme||x.objective;let app={id:'a_'+Date.now()+'_'+Math.random().toString(36).slice(2,6),ref:id,type:kind,title,stage:'Ide',deadline:kind==='competitions'&&/resmi/i.test(x.verification)?x.deadline:'',created:TODAY(),next:'Periksa syarat dan tanggal resmi',notes:'',url:x.url||x.source||''};store.applications.push(app);write();toast('Ditambahkan ke tracker');closeModal();render()}
function newApp(){showModal(`<h2>Tambah aplikasi baru</h2><p class="small">Gunakan untuk lowongan atau kompetisi yang belum masuk database.</p><form id="new-app-form"><div class="form-field"><label>Nama peluang *</label><input class="control" name="title" required maxlength="180" placeholder="Nama perusahaan / kompetisi / program" /></div><div class="form-grid"><div class="form-field"><label>Jenis</label><select class="control" name="type"><option value="competitions">Kompetisi</option><option value="companies">Pekerjaan</option><option value="scholarships">Beasiswa</option><option value="custom">Lainnya</option></select></div><div class="form-field"><label>Deadline (jika ada)</label><input type="date" class="control" name="deadline"/></div></div><div class="form-field"><label>Langkah berikut</label><input class="control" name="next" placeholder="Baca persyaratan, siapkan CV..."/></div><div class="form-field"><label>URL sumber</label><input class="control" type="url" name="url" placeholder="https://..."/></div><div class="modal-actions"><button type="button" class="button button-outline" data-close>Batal</button><button type="submit" class="button">Simpan ke tracker</button></div></form>`)}
function editApp(id){let a=store.applications.find(x=>x.id===id);if(!a)return;showModal(`<h2 style="margin-top:0">Edit aplikasi</h2><form id="edit-app-form" data-app-id="${safe(a.id)}"><div class="form-field"><label>Nama</label><input class="control" name="title" required maxlength="180" value="${safe(a.title)}"/></div><div class="form-grid"><div class="form-field"><label>Stage</label><select class="control" name="stage">${trackStages.map(x=>`<option ${a.stage===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field"><label>Deadline</label><input type="date" class="control" name="deadline" value="${safe(a.deadline||'')}"/></div></div><div class="form-field"><label>Next action</label><input class="control" name="next" value="${safe(a.next||'')}"/></div><div class="form-field"><label>URL sumber</label><input type="url" class="control" name="url" value="${safe(a.url||'')}"/></div><div class="form-field"><label>Catatan</label><textarea class="control" name="notes">${safe(a.notes||'')}</textarea></div><div class="modal-actions" style="justify-content:space-between"><button type="button" class="button button-danger" data-delete-app="${safe(a.id)}">Hapus</button><div class="row-actions"><button class="button button-outline" type="button" data-close>Batal</button><button class="button" type="submit">Simpan</button></div></div></form>`)}
function exportJSON(){const blob=new Blob([JSON.stringify({app:'greenpath-career-os',version:1,exportedAt:new Date().toISOString(),userData:store},null,2)],{type:'application/json'});downloadBlob(blob,'greenpath-backup-'+TODAY()+'.json')}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportCSV(){const fields=['id','name','scope','organizer','category','focus','cycle','deadline','window','prize','prizeType','eligibility','verification','format','warning','score','url','source','progress'];let csv='\uFEFF'+fields.join(',')+'\n'+D.competitions.map(x=>fields.map(f=>`"${String(f==='progress'?status('competitions',x.id):x[f]??'').replace(/"/g,'""')}"`).join(',')).join('\n');downloadBlob(new Blob([csv],{type:'text/csv;charset=utf-8'}),'greenpath-competition-bank-'+TODAY()+'.csv')}
function importModal(){showModal(`<h2>Restore data dari JSON</h2><p class="small">Impor backup akan <strong>mengganti</strong> semua progres yang sekarang tersimpan di browser ini. Bank referensi website tidak akan diubah. Ekspor backup saat ini sebelum impor jika perlu.</p><input class="control" id="import-file" type="file" accept="application/json,.json"/><div class="modal-actions"><button class="button button-outline" data-close>Batal</button><button class="button" data-import-confirm>Impor backup</button></div><div class="subtitle-divider"></div><p class="small">Reset hanya progres pribadi, bukan 89 lomba atau database perusahaan.</p><button class="button button-danger button-sm" data-reset>Reset semua progres</button>`)}
function onImport(){let file=document.getElementById('import-file')?.files?.[0];if(!file){toast('Pilih file JSON terlebih dahulu');return}if(file.size>5e6){toast('File terlalu besar, maksimal 5 MB');return}let rd=new FileReader();rd.onload=()=>{try{let obj=JSON.parse(String(rd.result));if(obj.app!=='greenpath-career-os'||!obj.userData||!Array.isArray(obj.userData.applications))throw Error('Invalid backup');if(!confirm('Ganti seluruh progres pada browser ini dengan backup?'))return;store={...structuredClone(def),...obj.userData};for(let k of Object.keys(def.statuses))store.statuses[k]=store.statuses[k]||{};write();closeModal();render();toast('Backup berhasil diimpor')}catch(e){toast('Format backup tidak sesuai')}};rd.readAsText(file)}
function fieldHTML(){return ''}
function navigate(){document.getElementById('sidebar').classList.remove('open');document.getElementById('sidebar-scrim').hidden=true;clearFilters();render();scrollTo({top:0,behavior:'auto'})}
window.addEventListener('hashchange',navigate);
function handleClick(e){
 let b=e.target.closest('button,[data-detail],[data-add],[data-fav],[data-more],[data-close],[data-backup],[data-import-open],[data-export-comps]');if(!b)return;
 if(b.matches('[data-detail]')){detail(b.dataset.detail,b.dataset.id);return}
 if(b.matches('[data-add]')){addApp(b.dataset.add,b.dataset.id);return}
 if(b.matches('[data-fav]')){const k=b.dataset.fav+':'+b.dataset.id;store.favorites[k]=!store.favorites[k];write();render();return}
 if(b.matches('[data-more]')){view.shown+=20;document.getElementById('comp-results').innerHTML=compResults();return}
 if(b.matches('[data-new-app]')){newApp();return}
 if(b.matches('[data-edit-app]')){editApp(b.dataset.editApp);return}
 if(b.matches('[data-close]')){closeModal();return}
 if(b.matches('[data-save-item-note]')){store.notes[b.dataset.saveItemNote+':'+b.dataset.id]=document.getElementById('item-note').value;write();toast('Catatan disimpan');closeModal();return}
 if(b.matches('[data-save-reading]')){store.notes.resources=document.getElementById('reading-notes').value;write();toast('Reading inbox disimpan');return}
 if(b.matches('[data-export-comps]')){exportCSV();return}
 if(b.matches('[data-backup]')){exportJSON();return}
 if(b.matches('[data-import-open]')){importModal();return}
 if(b.matches('[data-import-confirm]')){onImport();return}
 if(b.matches('[data-reset]')){if(confirm('Yakin ingin menghapus semua progress di perangkat ini? Tidak dapat dibatalkan tanpa backup.')){store=structuredClone(def);write();closeModal();render();toast('Progres direset')}return}
 if(b.matches('[data-delete-app]')){if(confirm('Hapus aplikasi ini dari tracker?')){store.applications=store.applications.filter(x=>x.id!==b.dataset.deleteApp);write();closeModal();render();toast('Aplikasi dihapus')}return}
 if(b.matches('[data-month]')){const [y,m]=view.month.split('-').map(Number),d=new Date(y,m-1+(b.dataset.month==='next'?1:-1),1);view.month=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');render();return}
}
document.addEventListener('click',handleClick);
document.getElementById('top-export').addEventListener('click',()=>exportJSON());
document.getElementById('footer-backup').addEventListener('click',()=>importModal());
document.getElementById('mobile-menu').addEventListener('click',()=>{document.getElementById('sidebar').classList.toggle('open');document.getElementById('sidebar-scrim').hidden=!document.getElementById('sidebar').classList.contains('open')});
document.getElementById('sidebar-scrim').addEventListener('click',()=>{document.getElementById('sidebar').classList.remove('open');document.getElementById('sidebar-scrim').hidden=true});
document.getElementById('modal-root').addEventListener('click',e=>{if(e.target.id==='overlay')closeModal()});
window.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();document.getElementById('sidebar').classList.remove('open');document.getElementById('sidebar-scrim').hidden=true}});
function onFilter(e){let el=e.target,k=el.dataset.filter;if(k){view[k]=el.value;view.shown=20;if(k==='q'&&document.getElementById('comp-results')){document.getElementById('comp-results').innerHTML=compResults();return}const pos=el.selectionStart;render();if(k==='q'){let input=document.querySelector('[data-filter="q"]');if(input){input.focus();try{input.setSelectionRange(pos,pos)}catch(_){}}}return}
 if(el.matches('[data-favs]')){view.favs=el.checked;render();return}
 if(el.matches('[data-tracker-type]')){view.trackerType=el.value;render();return}
 if(el.matches('[data-resource-group]')){view.resourceGroup=el.value;render();return}
 if(el.matches('[data-roadmap]')){store.statuses.roadmap[el.dataset.roadmap]=el.checked;write();render();return}
 if(el.matches('[data-weekly]')){store.weekly[el.dataset.weekly]=el.checked;write();render();return}
 if(el.matches('[data-change-status]')){store.statuses[el.dataset.kind][el.dataset.id]=el.value;write();render();return}
 if(el.matches('[data-skill]')){store.statuses.skills[el.dataset.skill]=Number(el.value);write();render();return}
 if(el.matches('[data-salary]')){const side=el.dataset.salary;store.salary[side]||={};store.salary[side][el.dataset.field]=el.value;write();const r=computeOffer(side),box=document.getElementById('offer-result-'+side);if(box)box.innerHTML=`<div class="small">Estimasi tabungan tahunan</div><strong>${rupiah(r.annual)}</strong><p class="small">Tabungan per bulan tanpa bonus: ${rupiah(r.monthly)} · Pendapatan net/jam: ${rupiah(r.eff)}</p>`;return}
}
document.addEventListener('input',e=>{if(e.target.matches('[data-filter="q"],[data-salary]'))onFilter(e)});
document.addEventListener('change',e=>{if(!e.target.matches('[data-filter="q"],[data-salary]'))onFilter(e)});
document.addEventListener('submit',e=>{const f=e.target;if(f.id==='new-app-form'){e.preventDefault();let d=Object.fromEntries(new FormData(f));let title=String(d.title||'').trim();if(!title)return;store.applications.push({id:'u_'+Date.now(),ref:'',type:d.type,title,stage:'Ide',deadline:d.deadline||'',next:d.next||'',url:safeURL(d.url),notes:'',created:TODAY()});write();closeModal();render();toast('Aplikasi ditambahkan')}else if(f.id==='edit-app-form'){e.preventDefault();let d=Object.fromEntries(new FormData(f)),app=store.applications.find(x=>x.id===f.dataset.appId);if(!app)return;Object.assign(app,{title:d.title,stage:d.stage,deadline:d.deadline,next:d.next,notes:d.notes,url:safeURL(d.url)});write();closeModal();render();toast('Perubahan disimpan')}});
let dragging='';document.addEventListener('dragstart',e=>{const c=e.target.closest('[data-card-id]');if(c){dragging=c.dataset.cardId;c.classList.add('dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',dragging)}});document.addEventListener('dragend',()=>{dragging='';document.querySelectorAll('.dragging,.drop-target').forEach(e=>e.classList.remove('dragging','drop-target'))});document.addEventListener('dragover',e=>{const lane=e.target.closest('[data-lane]');if(lane){e.preventDefault();lane.classList.add('drop-target')}});document.addEventListener('dragleave',e=>{let lane=e.target.closest('[data-lane]');if(lane&&!lane.contains(e.relatedTarget))lane.classList.remove('drop-target')});document.addEventListener('drop',e=>{let lane=e.target.closest('[data-lane]');if(lane&&dragging){e.preventDefault();let item=store.applications.find(a=>a.id===dragging);if(item){item.stage=lane.dataset.lane;write();render();toast('Stage diperbarui')}dragging=''}});
if(!location.hash)location.hash='dashboard';else render();
})();
